    while (true) {
      if (signal.aborted) fail('ABORTED');
      const part = await reader.read();
      if (part.done) break;
      if (!(part.value instanceof Uint8Array)) fail('LOCAL_CHAT_RESPONSE_INVALID');
      total += part.value.byteLength;
      if (total > cap) fail('LOCAL_CHAT_RESPONSE_TOO_LARGE');
      chunks.push(part.value);
    }
  } catch (error) { cancel(); throw error; }
  finally { signal.removeEventListener('abort', cancel); if (cancellation) await cancellation; try { reader.releaseLock(); } catch {} }
